// candela.mjs: load a pinned Candela copy, build presets, and split compiled.shared into its fixed and
// generated parts.
//
// Candela assembles every program as (src/compile.js, `const shared = ...`):
//   head + PRELUDE + SPECTRAL + ggxTableWGSL() + sdfCode + hfCode + densCode + CORE + metalAt + matCode + PATH
// PRELUDE, SPECTRAL, CORE and PATH are exported by src/kernel.js; ggxTableWGSL() is a constant; head only sets
// SPECTRAL_ON; metalAt, hitAlbedo and hitEmission are constant text generated by compile.js. splitProgram()
// checks every one of these boundaries and throws if any of them moved, so a new Candela version that
// assembles its program differently fails here instead of producing a wrong kernel.
//
// Callers pass the Candela root: firmware/third_party/candela, the vendored copy that its PIN.json pins
// (regenerate.mjs checks every file it reads against PIN.json before loading anything).
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// The Candela version the generators translate: candela-workspace(1).zip, SHA-256 873b2dd4...df5d. kernel.mjs
// writes this object into kernel/manifest.json; a Candela version bump changes it here and in PIN.json.
export const PIN = {
  archive: '873b2dd4bb9c32cac08751baf9fa6960ee4377306a04b2e118a8969dd940df5d',
  'src/kernel.js': '253d242df1a8827903e218c9ad119558d313f92da9f582ec3a25a6b8f7fb45c4',
  'src/compile.js': '6f5926cc1b8fe98a5ec3e3eb5dae0cc02efae75e67b115c99acca33aa2368f90',
  'src/render.js': 'a71df1b9404280196282c580d8436d1406d0193bc8744705e0c535d0c66e090a',
};

export function sha256(buf) { return createHash('sha256').update(buf).digest('hex'); }

// Refuse an unpinned Candela unless the caller asks for it explicitly (a version bump starts here).
export function checkPin(root, allowUnpinned = false) {
  const bad = [];
  for (const [rel, want] of Object.entries(PIN)) {
    if (rel === 'archive') continue;
    const got = sha256(readFileSync(join(root, rel)));
    if (got !== want) bad.push(`${rel}: ${got} (pinned ${want})`);
  }
  if (bad.length && !allowUnpinned) throw new Error('Candela copy differs from the pinned version:\n  ' + bad.join('\n  ') + '\n(pass --allow-unpinned to translate it anyway)');
  return bad;
}

export async function loadKernel(root) {
  return import(pathToFileURL(join(root, 'src/kernel.js')).href);
}
export async function loadCandela(root) {
  return import(pathToFileURL(join(root, 'src/candela.js')).href);
}

// The preset loader of build/build.js, without its esbuild dependency (as in PICOCALC-CANDELA-P4 01-census.mjs).
function frontmatter(src) {
  const m = src.match(/^---\n([\s\S]*?)\n---\n?/); if (!m) return {};
  const meta = {}; for (const line of m[1].split('\n')) { const k = line.match(/^([\w-]+):\s*(.*)$/); if (k) meta[k[1]] = k[2].trim(); }
  return meta;
}
export function loadPresets(root) {
  const dir = join(root, 'content/presets'), out = [];
  for (const f of readdirSync(dir).filter(f => f.endsWith('.md')).sort()) {
    const meta = frontmatter(readFileSync(join(dir, f), 'utf8'));
    const base = f.replace(/\.md$/, ''), files = { 'scene.js': readFileSync(join(dir, base + '.js'), 'utf8') };
    const lib = join(dir, base); if (existsSync(lib)) for (const g of readdirSync(lib)) files['lib/' + g] = readFileSync(join(lib, g), 'utf8');
    out.push({ id: meta.id, title: meta.title, base, files });
  }
  return out;
}

// Constant text that compile.js generates around the per-scene sections (copied from compile.js at the pin).
export const METAL_AT = 'fn metalAt(v: vec3f) -> vec3f {\n  if (SPECTRAL_ON) {\n    let t: f32 = clamp((gLam - 450.0) / 200.0, 0.0, 1.0);\n    let s: f32 = select(mix(v.z, v.y, t * 2.0), mix(v.y, v.x, t * 2.0 - 1.0), t > 0.5);\n    return vec3f(s, s, s);\n  }\n  return v;\n}\n';
export const HIT_ALBEDO = 'fn hitAlbedo(h: Hit, wo: vec3f) -> vec3f { let L: Lobe = evalMaterial(h, wo, 0.5); if (L.kind == 2 && (L.flags & 1) != 0) { return L.c1; } if (L.kind == 1 || L.kind == 4) { return L.c0; } return vec3f(0.8, 0.8, 0.8); }\n';
export const HIT_EMISSION = 'fn hitEmission(h: Hit, wo: vec3f) -> vec3f { let L: Lobe = evalMaterial(h, wo, 0.5); return L.Le; }\n';
export const DEFAULT_CUSTOM = 'fn customKernel(ro: vec3f, rd: vec3f) -> vec3f { return vec3f(1.0, 0.0, 1.0); }\n';

let ggxCache = null;
export function ggxWGSL(K) { if (!ggxCache) ggxCache = K.ggxTableWGSL(); return ggxCache; }

// Split one compiled program. Returns { spectral, fieldCode, matCode, customDefault } where fieldCode is
// sdfCode + hfCode + densCode and matCode is the material helpers, mat_k, evalMaterial and customKernel
// (hitAlbedo and hitEmission removed: they are fixed and live in the kernel).
export function splitProgram(shared, K) {
  const fail = (what) => { throw new Error('splitProgram: ' + what + ' (has Candela changed how compile.js assembles the program?)'); };
  const ggx = ggxWGSL(K);
  const iP = shared.indexOf(K.PRELUDE);
  if (iP < 0) fail('PRELUDE not found');
  const head = shared.slice(0, iP);
  const hm = head.match(/^const SPECTRAL_ON: bool = (true|false);\n$/);
  if (!hm) fail('unexpected head ' + JSON.stringify(head));
  let at = iP + K.PRELUDE.length;
  for (const [name, text] of [['SPECTRAL', K.SPECTRAL], ['ggxTableWGSL()', ggx]]) {
    if (shared.slice(at, at + text.length) !== text) fail(name + ' does not follow PRELUDE');
    at += text.length;
  }
  const iC = shared.indexOf(K.CORE, at);
  if (iC < 0) fail('CORE not found');
  const fieldCode = shared.slice(at, iC);
  at = iC + K.CORE.length;
  if (shared.slice(at, at + METAL_AT.length) !== METAL_AT) fail('metalAt does not follow CORE');
  at += METAL_AT.length;
  if (!shared.endsWith(K.PATH)) fail('the program does not end with PATH');
  let matCode = shared.slice(at, shared.length - K.PATH.length);
  for (const [name, text] of [['hitAlbedo', HIT_ALBEDO], ['hitEmission', HIT_EMISSION]]) {
    const n = matCode.split(text).length - 1;
    if (n !== 1) fail(`${name} appears ${n} times in the material section`);
    matCode = matCode.replace(text, '');
  }
  for (const fn of ['sdUser', 'heightAt', 'densityOf']) if (!new RegExp(`\\bfn ${fn}\\(`).test(fieldCode)) fail(fn + ' missing from the field section');
  for (const fn of ['evalMaterial', 'customKernel']) if (!new RegExp(`\\bfn ${fn}\\(`).test(matCode)) fail(fn + ' missing from the material section');
  return { spectral: hm[1] === 'true', fieldCode, matCode, customDefault: matCode.includes(DEFAULT_CUSTOM) };
}

// The fixed WGSL, in program order, as one string per part (what the firmware kernel is translated from).
export function fixedParts(K) {
  return [['PRELUDE', K.PRELUDE], ['SPECTRAL', K.SPECTRAL], ['GGX', ggxWGSL(K)], ['CORE', K.CORE], ['METAL', METAL_AT],
          ['HITFN', HIT_ALBEDO + HIT_EMISSION], ['PATH', K.PATH]];
}

// Uniform rows 0-5, 20, 21 as src/viewport.js fills them before a dispatch (PICOCALC-CANDELA-P4 03-export-scene.mjs).
export async function exportScene(root, C, preset, W, H) {
  const { cameraUniforms } = await import(pathToFileURL(join(root, 'src/compile.js')).href);
  const r = await C.build(preset.files);
  if (!r.ok) throw r.error;
  const c = r.compiled;
  const pk = c.pack({ time: 0 });
  const U = pk.U, integ = c.engine.integrator || {};
  const cam = cameraUniforms(c.cameraComp, { width: W, height: H, time: 0 });
  const mode = { path: 0, albedo: 1, normals: 2, depth: 3, ao: 4, custom: 9 }[integ.__integrator] || 0;
  U.set([W, H, 0, 1], 0);
  U.set(cam.U1, 4); U.set(cam.U2, 8); U.set(cam.U3, 12); U.set(cam.U4, 16);
  U.set([1, integ.maxDepth || 8, integ.rrAfter || 3, (integ.nee === false ? 0 : 1) | (integ.mis === 'none' ? 0 : 2)], 20);
  U[80] = cam.bladeRot || 0; U[81] = integ.radius || 0.5; U[82] = integ.clamp || 0;
  U[84] = 1; U[85] = 1; U[86] = 1; U[87] = mode; U[96] = 0;
  const sdRows = Math.max(pk.dynBase + pk.SDd.length / 4, pk.SDs.length / 4, 1);
  const SD = new Float32Array(sdRows * 4); SD.set(pk.SDs, 0); SD.set(pk.SDd, pk.dynBase * 4);
  const parts = [U, pk.O, pk.LI, pk.BV, SD];
  const headWords = new Uint32Array([0x314c4443, ...parts.map(p => p.length / 4)]);
  const bin = Buffer.concat([Buffer.from(headWords.buffer), ...parts.map(p => Buffer.from(p.buffer, p.byteOffset, p.byteLength))]);
  const meta = { preset: preset.id, title: preset.base, width: W, height: H, rows: parts.map(p => p.length / 4),
    ev: cam.ev, exposureMode: cam.mode, physicalEV: cam.physical, engine: c.engine.name, maxDepth: integ.maxDepth, rrAfter: integ.rrAfter,
    integrator: integ.__integrator || 'path', objects: c.stats.objects, materials: c.stats.materials, wgslLines: c.stats.lines,
    post: (c.engine.post || []).map(p => p.__pass + (p.op ? ':' + p.op : '')) };
  return { compiled: c, bin, meta };
}
